<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
final class InventoryView
{
    private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
    private static function input(string $label,string $name,string $value=''):string{return '<label>'.self::h($label).'<input name="'.self::h($name).'" value="'.self::h($value).'" required></label>';}
    private static function form(array $s,string $csrf,string $op):string{
        $html='<form method="post">';foreach(['_csrf'=>$csrf,'action'=>'inventory-'.$op,'merchant'=>$s['merchant'],'outlet'=>$s['outlet'],'request'=>bin2hex(random_bytes(16))] as $k=>$v)$html.='<input type="hidden" name="'.$k.'" value="'.self::h($v).'">';return $html;
    }
    private static function items(array $s):string{$html='<label>Ingredient<select name="item">';foreach($s['items'] as $i)$html.='<option value="'.$i['item_id'].'">'.self::h($i['name'].' · '.$i['unit']).'</option>';return $html.'</select></label>';}
    public static function render(array $s,string $csrf,string $message='',bool $error=false):string{
        $h=static fn($v)=>self::h($v);$url='/merchant.php?inventory=1&merchant='.$s['merchant'].'&outlet='.$s['outlet'];$low=array_filter($s['items'],fn($i)=>$i['stock_state']!=='In stock');
        $html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/inventory.css"><script src="/assets/inventory.js" defer></script></head><body><main data-inventory data-merchant="'.$s['merchant'].'" data-outlet="'.$s['outlet'].'"><header><div><p class="eyebrow">Restaurant operations · Private demonstration</p><h1>Inventory & recipes</h1><p>Track ingredients in this outlet. Stock is never deducted by public orders.</p></div></header><nav aria-label="Inventory sections">';
        foreach(['stock'=>'Stock overview','ingredients'=>'Ingredients','movements'=>'Record stock','recipes'=>'Recipes','alerts'=>'Low stock','history'=>'History'] as $id=>$name)$html.='<a href="#'.$id.'">'.$name.'</a>';
        $html.='</nav>';if($message!=='')$html.='<p class="message'.($error?' error':'').'" role="'.($error?'alert':'status').'">'.$h($message).'</p>';
        $html.='<section class="merchant-metrics" aria-label="Inventory overview"><article><strong>'.count($s['items']).'</strong><span>Ingredients in this outlet</span></article><article><strong>'.count($low).'</strong><span>Threshold alerts</span></article><article><strong>'.count($s['recipes']).'</strong><span>Retained recipe versions</span></article></section><section class="panel" id="stock"><h2>Stock overview</h2><label>Search ingredients<input type="search" data-stock-search></label><label>Stock status<select data-stock-status><option value="">All stock</option>Low stock</option><option>Exhausted</option><option>In stock</option></select></label><p role="status" data-stock-count></p><div class="inventory-table-wrap"><table><caption>Current outlet stock — base units only</caption><thead><tr><th scope="col">Ingredient</th><th scope="col">Current stock</th><th scope="col">Minimum</th><th scope="col">Status</th><th scope="col">Storage</th></tr></thead><tbody>';
        foreach($s['items'] as $i)$html.='<tr data-stock-row data-state="'.$h($i['stock_state']).'"><th scope="row">'.$h($i['name']).'</th><td>'.Inventory::display((int)$i['balance_milli']).' '.$h($i['unit']).'</td><td>'.Inventory::display((int)$i['minimum_milli']).' '.$h($i['unit']).'</td><td>'.$h($i['stock_state']).'</td><td>'.$h($i['location_label']).'</td></tr>';
        $html.='</tbody></table></div>'.(!$s['items']?'<p>No ingredients yet. Add an ingredient below to begin.</p>':'').'</section><section class="panel" id="ingredients"><h2>Ingredients & storage</h2>'.self::form($s,$csrf,'ingredient').self::input('Ingredient name','name').'<label>Base measurement unit<select name="unit"><option value="g">Grams (g)</option><option value="ml">Millilitres (ml)</option><option value="each">Each</option></select></label>'.self::input('Opening quantity','opening','0').self::input('Minimum quantity','minimum','0').self::input('Storage location','location','Main store').self::input('Supplier reference (plain text; no orders are sent)','supplier','Not specified').'<button>Add ingredient</button></form>';
        foreach($s['items'] as $i){$html.='<details><summary>Edit '.$h($i['name']).'</summary>'.self::form($s,$csrf,'update');foreach(['item'=>$i['item_id'],'version'=>$i['version']] as $k=>$v)$html.='<input type="hidden" name="'.$k.'" value="'.$v.'">';$html.=self::input('Name','name',$i['name']).self::input('Minimum quantity · '.$i['unit'],'minimum',Inventory::display((int)$i['minimum_milli'])).self::input('Storage','location',$i['location_label']).self::input('Supplier reference','supplier',$i['supplier_reference']).'<p>Base unit cannot be changed; existing ledger quantities retain their meaning.</p><button>Save ingredient</button></form></details>';}
        $html.='</section><section class="panel" id="movements"><h2>Record stock</h2><p>Quantities use the selected ingredient’s base unit; convert kg to g and litres to ml before entry. Use up to three decimal places.</p>';
        if($s['items'])foreach(['receipt'=>'Stock receipt','adjustment'=>'Manual adjustment','wastage'=>'Record wastage'] as $op=>$name){$html.='<details><summary>'.$name.'</summary>'.self::form($s,$csrf,$op).self::items($s).self::input('Quantity','quantity');if($op==='adjustment')$html.='<label>Direction<select name="direction"><option>increase</option><option>decrease</option></select></label>';$html.=self::input('Reason or reference','reason').'<button>'.$name.'</button></form></details>';}
        else $html.='<p>Add an ingredient before recording movements.</p>';
        $html.='</section><section class="panel" id="recipes"><h2>Recipe versions</h2><p>Each version defines base-unit consumption for one standard product serving. Saving creates a new immutable version. Existing calculations keep their original recipe reference.</p>';
        if($s['items']&&$s['products']){$html.=self::form($s,$csrf,'recipe').'<label>Product<select name="product">';foreach($s['products'] as $p)$html.='<option value="'.$p['product_id'].'">'.$h($p['name']).'</option>';$html.='</select></label>';foreach($s['items'] as $n=>$i){$html.='<fieldset><legend>'.$h($i['name']).'</legend><input type="hidden" name="lines['.$n.'][item]" value="'.$i['item_id'].'"><input type="hidden" name="lines['.$n.'][unit]" value="'.$i['unit'].'"><label>Quantity per standard serving · '.$i['unit'].'<input name="lines['.$n.'][quantity]" value="0" inputmode="decimal"></label></fieldset>';}$html.='<p>Leave unused ingredients at zero. At least one positive ingredient is required.</p><button>Save recipe version</button></form>';}
        else $html.='<p>Add ingredients and a product before creating a recipe.</p>';
        foreach($s['recipes'] as $recipe){$product=array_values(array_filter($s['products'],fn($p)=>(int)$p['product_id']===(int)$recipe['product_id']));$html.='<details data-recipe="'.$recipe['recipe_id'].'"><summary>'.$h($product[0]['name']??'Retained product').' · recipe version '.$recipe['revision'].'</summary><ul>';foreach(json_decode($recipe['lines_json'],true) as $id=>$line){$item=array_values(array_filter($s['items'],fn($i)=>$i['item_id']===$id));$html.='<li>'.$h($item[0]['name']??$id).' · '.Inventory::display($line['quantity_milli']).' '.$h($line['unit']).'</li>';}$html.='</ul>'.self::form($s,$csrf,'consume').'<input type="hidden" name="recipe" value="'.$recipe['recipe_id'].'">'.self::input('Synthetic standard servings','servings','1').self::input('Consumption reason','reason','Synthetic preparation trial').'<button>Record authorized consumption</button></form></details>';}
        $html.='</section><section class="panel" id="alerts"><h2>Low-stock centre</h2><p>Review stock and supplier references. No purchasing or product-availability changes are automated.</p>';foreach($low as $i)$html.='<article><h3>'.$h($i['name']).' — '.$h($i['stock_state']).'</h3><p>Current '.Inventory::display((int)$i['balance_milli']).' / minimum '.Inventory::display((int)$i['minimum_milli']).' '.$h($i['unit']).'. Review this outlet’s stock record.</p></article>';if(!$low)$html.='<p>No ingredients currently need threshold review.</p>';
        $html.='</section><section class="panel" id="history"><h2>Stock & configuration history</h2><p>Most recent 200 immutable events. Times are UTC. Corrections append compensating movements; history is never edited.</p>';
        foreach($s['history'] as $e){$html.='<details><summary>'.$h($e['operation']).' · '.gmdate('Y-m-d H:i:s',(int)$e['occurred_epoch']).' UTC · '.$h($e['display_name']).'</summary><p>Request '.$h($e['request_id']).'</p><ul>';foreach($s['movements'] as $v)if($v['request_id']===$e['request_id']){$n=(int)$v['delta_milli'];$html.='<li>'.$h($v['name']).' '.($n<0?'−':'+').Inventory::display(abs($n)).' '.$h($v['unit']).' → '.Inventory::display((int)$v['balance_after_milli']).' '.$h($v['unit']).'</li>';}$html.='</ul>';if(in_array($e['operation'],['ingredient','receipt','adjustment','wastage','consume'],true))$html.=self::form($s,$csrf,'reverse').'<input type="hidden" name="original" value="'.$e['request_id'].'">'.self::input('Correction reason','reason').'<button>Reverse stock movement</button></form>';$html.='</details>';}
        return $html.'</section></main></body></html>';
    }
}
